class LibvirtConfigDomainCapsTpm(LibvirtConfigObject):

    def __init__(self, **kwargs):
        super().__init__(root_name='tpm', **kwargs)
        self.supported = False
        self.models = []
        self.backend_models = []
        # TODO(tkajinam): Change default to [] once libvirt >= 8.6.0 is
        #                 required
        self.backend_versions = None

    def parse_dom(self, xmldoc):
        super(LibvirtConfigDomainCapsTpm, self).parse_dom(xmldoc)

        if xmldoc.get('supported'):
            self.supported = (xmldoc.get('supported') == 'yes')
        for c in xmldoc:
            if c.tag == 'enum':
                if c.get('name') == 'model':
                    for c2 in c:
                        if c2.tag == 'value':
                            self.models.append(c2.text)
                if c.get('name') == 'backendModel':
                    for c2 in c:
                        if c2.tag == 'value':
                            self.backend_models.append(c2.text)
                if c.get('name') == 'backendVersion':
                    for c2 in c:
                        if c2.tag == 'value':
                            if self.backend_versions is None:
                                self.backend_versions = []
                            self.backend_versions.append(c2.text)


class LibvirtConfigDomainCapsDevices(LibvirtConfigObject):
    DEVICE_PARSERS = {
        'video': LibvirtConfigDomainCapsVideoModels,
        'disk': LibvirtConfigDomainCapsDiskBuses,
        'tpm': LibvirtConfigDomainCapsTpm,
    }

    def __init__(self, **kwargs):
        super().__init__(root_name='devices', **kwargs)
        self.devices = set()

    def parse_dom(self, xmldoc):
        super().parse_dom(xmldoc)

        for c in list(xmldoc):
            device = self.DEVICE_PARSERS.get(c.tag)
            if device:
                device = device()
                device.parse_dom(c)
                self.devices.add(device)

    def _get_device(self, device_type):
        for device in self.devices:
            if type(device) is self.DEVICE_PARSERS.get(device_type):
                return device
        return None

    @property
    def disk(self):
        return self._get_device('disk')

    @property
    def video(self):
        return self._get_device('video')

    @property
    def tpm(self):
        return self._get_device('tpm')


class LibvirtConfigDomainCapsFeatures(LibvirtConfigObject):

    def __init__(self, **kwargs):
        super(LibvirtConfigDomainCapsFeatures, self).__init__(
            root_name="features", **kwargs)
        self.features = []

    def parse_dom(self, xmldoc):
        super(LibvirtConfigDomainCapsFeatures, self).parse_dom(xmldoc)

        for c in xmldoc:
            feature = None
            if c.tag == "sev":
                feature = LibvirtConfigDomainCapsFeatureSev()
            if feature:
                feature.parse_dom(c)
                self.features.append(feature)

            # There are many other features and domain capabilities,
            # but we don't need to regenerate the XML (it's read-only
            # data provided by libvirtd), so there's no point parsing
            # them until we actually need their values.

    # For the same reason, we do not need a format_dom() method, but
    # it's a bug if this ever gets called and we inherited one from
    # the base class, so override that to watch out for accidental
    # calls.
    def format_dom(self):
        raise RuntimeError(_('BUG: tried to generate domainCapabilities XML'))


